def encrypt(s):
    encrypted = ""
    for char in s:
        if char.isalpha():
            shift = 4
            if char.isupper():
                start = ord('A')
            else:
                start = ord('a')
            encrypted += chr((ord(char) - start + shift) % 26 + start)
        else:
            encrypted += char
    return encrypted

